import { defaultTheme, contrastStorageKey, colorVisionStorageKey, glowStorageKey, isThemeName, themeStorageKey, } from "./theme.js";
export const themeChangeEvent = "otf:themechange";
export const appearanceChangeEvent = "otf:appearancechange";
export function getActiveTheme() {
    if (typeof document === "undefined")
        return defaultTheme;
    const current = document.documentElement.dataset.theme;
    return isThemeName(current) ? current : defaultTheme;
}
export function setActiveTheme(theme) {
    if (typeof document === "undefined")
        return;
    document.documentElement.dataset.theme = theme;
    try {
        localStorage.setItem(themeStorageKey, theme);
    }
    catch {
        // Theme changes still apply when storage is unavailable.
    }
    window.dispatchEvent(new CustomEvent(themeChangeEvent, {
        detail: { theme },
    }));
}
export function getReducedGlow() {
    return typeof document !== "undefined" && document.documentElement.dataset.glow === "reduced";
}
export function getHighContrast() {
    return typeof document !== "undefined" && document.documentElement.dataset.contrast === "high";
}
export function getColorSafe() {
    return typeof document !== "undefined" && document.documentElement.dataset.colorVision === "safe";
}
function emitAppearanceChange() {
    window.dispatchEvent(new CustomEvent(appearanceChangeEvent, {
        detail: {
            reducedGlow: getReducedGlow(),
            highContrast: getHighContrast(),
            colorSafe: getColorSafe(),
        },
    }));
}
export function setReducedGlow(enabled) {
    if (typeof document === "undefined")
        return;
    document.documentElement.dataset.glow = enabled ? "reduced" : "standard";
    try {
        localStorage.setItem(glowStorageKey, enabled ? "true" : "false");
    }
    catch {
        // Appearance changes still apply when storage is unavailable.
    }
    emitAppearanceChange();
}
export function setHighContrast(enabled) {
    if (typeof document === "undefined")
        return;
    document.documentElement.dataset.contrast = enabled ? "high" : "standard";
    try {
        localStorage.setItem(contrastStorageKey, enabled ? "true" : "false");
    }
    catch {
        // Appearance changes still apply when storage is unavailable.
    }
    emitAppearanceChange();
}
export function setColorSafe(enabled) {
    if (typeof document === "undefined")
        return;
    document.documentElement.dataset.colorVision = enabled ? "safe" : "standard";
    try {
        localStorage.setItem(colorVisionStorageKey, enabled ? "true" : "false");
    }
    catch {
        // Appearance changes still apply when storage is unavailable.
    }
    emitAppearanceChange();
}
